/**
 * Proxy API Service
 * 
 * Features:
 * - SSRF (Server-Side Request Forgery) Protection
 * - Input Validation
 * - Request Timeouts & Size Limits
 * - Rate Limiting
 * - Comprehensive Error Handling
 */

const express = require('express');
const axios = require('axios');
const validator = require('validator');
const ipaddr = require('ipaddr.js');
const dns = require('dns').promises;
const rateLimit = require('express-rate-limit');

const app = express();
app.use(express.json());

// Configuration
const PORT = process.env.PORT || 3000;
const MAX_RESPONSE_SIZE = 1024 * 1024; // 1MB limit
const REQUEST_TIMEOUT = 5000; // 5 seconds

// Rate limiting to prevent abuse
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per window
    message: { error: 'Too many requests, please try again later.' }
});

app.use('/fetch', limiter);

/**
 * Validates the URL and checks for SSRF vulnerabilities by resolving 
 * the hostname and checking against private IP ranges.
 */
async function validateUrlSecurity(urlStr) {
    try {
        const parsedUrl = new URL(urlStr);

        // 1. Protocol validation
        if (!['http:', 'https:'].includes(parsedUrl.protocol)) {
            throw new Error('Invalid protocol. Only HTTP and HTTPS are allowed.');
        }

        // 2. Hostname validation
        const hostname = parsedUrl.hostname;
        if (!hostname || validator.isIP(hostname)) {
            // If it's a direct IP, check it immediately
            if (isPrivateIP(hostname)) throw new Error('Access to private network is forbidden.');
        } else {
            // Resolve DNS to check the underlying IP
            const addresses = await dns.resolve4(hostname);
            if (addresses.some(addr => isPrivateIP(addr))) {
                throw new Error('Hostname resolves to a private network address.');
            }
        }

        return true;
    } catch (err) {
        throw new Error(`URL Validation Failed: ${err.message}`);
    }
}

/**
 * Checks if an IP address belongs to a private or reserved range.
 */
function isPrivateIP(ip) {
    try {
        const addr = ipaddr.parse(ip);
        const range = addr.range();
        // 'unicast' usually implies public internet for IPv4
        // We block loopback, linkLocal, private, multicast, etc.
        return range !== 'unicast';
    } catch (e) {
        return true; // Treat unparseable IPs as unsafe
    }
}

/**
 * POST /fetch
 * Body: { "url": "https://example.com" }
 */
app.post('/fetch', async (req, res) => {
    const { url } = req.body;

    // 1. Basic Input Validation
    if (!url || typeof url !== 'string' || !validator.isURL(url)) {
        return res.status(400).json({ error: 'A valid URL is required.' });
    }

    try {
        // 2. SSRF Security Check
        await validateUrlSecurity(url);

        // 3. Perform Request
        const response = await axios({
            method: 'get',
            url: url,
            timeout: REQUEST_TIMEOUT,
            maxContentLength: MAX_RESPONSE_SIZE,
            // Prevent decompression bombs by limiting max body length
            maxBodyLength: MAX_RESPONSE_SIZE,
            headers: {
                'User-Agent': 'ProxyService/1.0.0',
                'Accept': 'application/json, text/plain, */*'
            },
            // Do not follow redirects automatically to prevent redirect-based SSRF
            maxRedirects: 0, 
            validateStatus: (status) => status >= 200 && status < 300
        });

        // 4. Return Data
        return res.status(200).json({
            status: response.status,
            headers: {
                'content-type': response.headers['content-type']
            },
            data: response.data
        });

    } catch (error) {
        // 5. Structured Error Handling
        if (error.response) {
            // External server responded with non-2xx
            return res.status(502).json({ 
                error: 'External server returned an error', 
                details: error.response.status 
            });
        } else if (error.code === 'ECONNABORTED') {
            return res.status(504).json({ error: 'Request timed out' });
        } else {
            return res.status(400).json({ 
                error: error.message || 'An unexpected error occurred' 
            });
        }
    }
});

// Global Error Handler
app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(PORT, () => {
    console.log(`Proxy API running on port ${PORT}`);
});
